// PlayerController.cs — todo en un solo MonoBehaviour
using UnityEngine;

public class PlayerController : MonoBehaviour
{
    [Header("Movement")]
    [SerializeField] private float moveSpeed = 8f;
    [SerializeField] private float jumpForce = 12f;

    [Header("Health")]
    [SerializeField] private int maxHealth = 100;
    private int _currentHealth;

    [Header("Score")]
    private int _score;
    private Vector3 _checkpointPos;

    private Rigidbody2D _rb;
    private bool _isGrounded;

    private void Awake()
    {
        _rb = GetComponent<Rigidbody2D>();
        _currentHealth = maxHealth;
    }

    // Input + movimiento en Update
    private void Update()
    {
        float h = Input.GetAxisRaw("Horizontal");
        _rb.linearVelocity = new Vector2(h * moveSpeed, _rb.linearVelocity.y);

        if (Input.GetButtonDown("Jump") && _isGrounded)
            _rb.AddForce(Vector2.up * jumpForce, ForceMode2D.Impulse);

        // Detección de suelo
        _isGrounded = Physics2D.Raycast(
            transform.position, Vector2.down, 0.1f);
    }

    // Física adicional en FixedUpdate
    private void FixedUpdate()
    {
        // Limitar velocidad de caída
        if (_rb.linearVelocity.y < -20f)
            _rb.linearVelocity = new Vector2(_rb.linearVelocity.x, -20f);
    }

    // ---- Salud ----
    public void TakeDamage(int amount)
    {
        _currentHealth -= amount;
        Debug.Log($"HP restante: {_currentHealth}");
        if (_currentHealth <= 0) Die();
    }

    public void Heal(int amount)
    {
        _currentHealth = Mathf.Min(_currentHealth + amount, maxHealth);
    }

    private void Die()
    {
        Debug.Log("Player died");
        transform.position = _checkpointPos;
        _currentHealth = maxHealth;
    }

    // ---- Puntuación ----
    public void AddScore(int points)
    {
        _score += points;
        // Actualiza la UI directamente desde aquí
        FindObjectOfType<ScoreUI>().UpdateDisplay(_score);
    }

    // ---- Checkpoint ----
    public void SaveCheckpoint(Vector3 position)
    {
        _checkpointPos = position;
        Debug.Log($"Checkpoint guardado en {position}");
    }
}

