[RequireComponent(typeof(Rigidbody2D), typeof(PlayerInput))]
public class PlayerMovement : MonoBehaviour
{
    [SerializeField] private float moveSpeed = 8f;
    [SerializeField] private float jumpForce = 12f;

    private Rigidbody2D _rb;
    private PlayerInput _input;
    private bool _isGrounded;

    private void Awake()
    {
        _rb    = GetComponent<Rigidbody2D>();
        _input = GetComponent<PlayerInput>();
        _input.OnMove += HandleMove;
        _input.OnJump += HandleJump;
    }

    private void HandleMove(float h) =>
        _rb.linearVelocity = new Vector2(h * moveSpeed, _rb.linearVelocity.y);

    private void HandleJump()
    {
        _isGrounded = Physics2D.Raycast(transform.position, Vector2.down, 0.1f);
        if (_isGrounded)
            _rb.AddForce(Vector2.up * jumpForce, ForceMode2D.Impulse);
    }

    private void FixedUpdate()
    {
        if (_rb.linearVelocity.y < -20f)
            _rb.linearVelocity = new Vector2(_rb.linearVelocity.x, -20f);
    }
}

// PlayerHealth.cs — SOLO salud y respawn
using System;
using UnityEngine;

public class PlayerHealth : MonoBehaviour
{
    [SerializeField] private int maxHealth = 100;
    private int _currentHealth;
    private Vector3 _checkpointPos;

    public event Action<int, int> OnHealthChanged; // current, max

    private void Awake() => _currentHealth = maxHealth;

    public void TakeDamage(int amount)
    {
        _currentHealth = Mathf.Max(0, _currentHealth - amount);
        OnHealthChanged?.Invoke(_currentHealth, maxHealth);
        if (_currentHealth == 0) Respawn();
    }

    public void Heal(int amount)
    {
        _currentHealth = Mathf.Min(_currentHealth + amount, maxHealth);
        OnHealthChanged?.Invoke(_currentHealth, maxHealth);
    }

    public void SaveCheckpoint(Vector3 pos) => _checkpointPos = pos;

    private void Respawn()
    {
        transform.position = _checkpointPos;
        _currentHealth = maxHealth;
        OnHealthChanged?.Invoke(_currentHealth, maxHealth);
    }
}

