using System.Collections.Generic;
using UnityEngine;

public class InventoryMonoBehaviour : MonoBehaviour
{
    [SerializeField] private int maxSlots = 20;
    [SerializeField] private AudioClip pickupSound;
    private AudioSource _audio;

    // Datos mezclados con el MonoBehaviour
    public List<ItemData> Items = new List<ItemData>();
    private ItemData _equippedWeapon;
    private ItemData _equippedArmor;

    private void Awake() => _audio = GetComponent<AudioSource>();

    // Lógica de negocio dentro del MonoBehaviour
    public bool TryAddItem(ItemData item)
    {
        if (Items.Count >= maxSlots) return false;
        if (Items.Contains(item)) return false;
        Items.Add(item);
        _audio.PlayOneShot(pickupSound); // UI/audio mezclado con negocio
        return true;
    }

    public ItemData FindItemById(string id) =>
        Items.Find(i => i.Id == id);

    public bool Equip(string itemId)
    {
        ItemData item = FindItemById(itemId);
        if (item == null || !item.IsEquippable) return false;
        if (item.Slot == EquipSlot.Weapon)   _equippedWeapon = item;
        if (item.Slot == EquipSlot.Armor)    _equippedArmor  = item;
        FindObjectOfType<EquipmentUI>().Refresh(); // acoplamiento directo a UI
        return true;
    }

    public void SaveToPlayerPrefs()
    {
        // Serialización hardcodeada en el MonoBehaviour
        string json = JsonUtility.ToJson(new InventoryData(Items));
        PlayerPrefs.SetString("inventory", json);
    }

    public float GetTotalWeight() =>
        Items.Sum(i => i.Weight);
}

