using System;
using System.Collections.Generic;
using System.Linq;

public class Inventory
{
    private readonly int _maxSlots;
    private readonly List<ItemData> _items = new List<ItemData>();

    private ItemData _equippedWeapon;
    private ItemData _equippedArmor;

    // Eventos para notificar cambios — sin referencias a UI ni audio
    public event Action<ItemData> OnItemAdded;
    public event Action<ItemData> OnItemRemoved;
    public event Action<ItemData, EquipSlot> OnEquipChanged;

    public IReadOnlyList<ItemData> Items => _items.AsReadOnly();

    public Inventory(int maxSlots) => _maxSlots = maxSlots;

    public bool TryAddItem(ItemData item)
    {
        if (_items.Count >= _maxSlots) return false;
        if (_items.Contains(item)) return false;
        _items.Add(item);
        OnItemAdded?.Invoke(item);
        return true;
    }

    public ItemData FindById(string id) => _items.FirstOrDefault(i => i.Id == id);

    public bool Equip(string itemId)
    {
        ItemData item = FindById(itemId);
        if (item == null || !item.IsEquippable) return false;
        if (item.Slot == EquipSlot.Weapon)  _equippedWeapon = item;
        if (item.Slot == EquipSlot.Armor)   _equippedArmor  = item;
        OnEquipChanged?.Invoke(item, item.Slot);
        return true;
    }

    public float GetTotalWeight() => _items.Sum(i => i.Weight);
}

// InventoryController.cs — MonoBehaviour fachada que conecta con Unity
using UnityEngine;

public class InventoryController : MonoBehaviour
{
    [SerializeField] private int maxSlots = 20;
    [SerializeField] private AudioClip pickupSound;
    [SerializeField] private EquipmentUI equipmentUI;

    private Inventory _inventory;
    private AudioSource _audio;

    private void Awake()
    {
        _audio     = GetComponent<AudioSource>();
        _inventory = new Inventory(maxSlots);

        // Suscribir efectos secundarios de Unity a los eventos del POCO
        _inventory.OnItemAdded    += _ => _audio.PlayOneShot(pickupSound);
        _inventory.OnEquipChanged += (_, __) => equipmentUI.Refresh();
    }

    public bool TryAddItem(ItemData item) => _inventory.TryAddItem(item);
    public bool Equip(string id)          => _inventory.Equip(id);
    public float GetTotalWeight()         => _inventory.GetTotalWeight();

    public void Save()
    {
        // Serialización queda en el controller, no en la lógica de negocio
        string json = JsonUtility.ToJson(new InventoryData(_inventory.Items));
        PlayerPrefs.SetString("inventory", json);
    }
}

