// ItemData.cs — datos, UI, serialización y comparación en una sola clase
using System;
using System.Collections.Generic;
using UnityEngine;

[Serializable]
public class ItemData
{
    // --- Datos del item ---
    public string Id;
    public string Name;
    public int    Damage;
    public int    Defense;
    public float  Weight;
    public Rarity Rarity;
    public bool   IsEquippable;
    public EquipSlot Slot;

    // --- Construcción de tooltip HTML (responsabilidad de UI) ---
    public string BuildTooltip()
    {
        string color = Rarity == Rarity.Legendary ? "#FFD700" : "#FFFFFF";
        return $"<color={color}><b>{Name}</b></color>\n" +
               $"<size=12>Daño: {Damage} | Defensa: {Defense}</size>\n" +
               $"Peso: {Weight:F1} kg\n" +
               $"<i>{Rarity}</i>";
    }

    // --- Serialización a JSON (responsabilidad de I/O) ---
    public string ToJson() => JsonUtility.ToJson(this);

    public static ItemData FromJson(string json) =>
        JsonUtility.FromJson<ItemData>(json);

    public Dictionary<string, object> ToDict() => new()
    {
        { "id",     Id     },
        { "name",   Name   },
        { "damage", Damage },
        { "weight", Weight }
    };

    // --- Comparación para inventario (responsabilidad de lógica) ---
    public bool IsBetterThan(ItemData other)
    {
        if (Slot != other.Slot) return false;
        return (Damage + Defense) > (other.Damage + other.Defense);
    }

    public int ComparePower(ItemData other) =>
        (Damage + Defense).CompareTo(other.Damage + other.Defense);
}

